interface SpinnerIconProps {
    color: string
    backgroundColor: string
    style?: React.CSSProperties
}

export function SpinnerIcon(props: SpinnerIconProps) {
    const borderWidth = 3

    return (
        <div style={{ position: "relative", ...props.style }}>
            <motion.div
                animate={{ rotate: 360 }}
                transition={{
                    ease: "linear",
                    duration: 1,
                    repeat: Infinity,
                }}
                style={{
                    borderRadius: 100,
                    backgroundImage: `conic-gradient(from 270deg, transparent 0%, ${props.color} 100%)`,
                    width: "100%",
                    height: "100%",
                }}
            />
            <div
                style={{
                    backgroundColor: props.backgroundColor,
                    borderRadius: 100,
                    position: "absolute",
                    top: borderWidth,
                    left: borderWidth,
                    bottom: borderWidth,
                    right: borderWidth,
                }}
            />
        </div>
    )
}
